#include "sdf/bounded_oracle.hpp"
#include "sdf/ray.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <chrono>
#ifdef _WIN32
#define NOMINMAX
#include <windows.h>
#include <psapi.h>
#endif
namespace {using namespace sdf;namespace fs=std::filesystem;
std::size_t peak(){
#ifdef _WIN32
PROCESS_MEMORY_COUNTERS counter{};if(GetProcessMemoryInfo(GetCurrentProcess(),&counter,sizeof(counter)))return counter.PeakWorkingSetSize;
#endif
return 0;}
void guard(){if(peak()>1610612736)throw std::runtime_error("Declared process working-set limit exceeded");}
std::array<double,8> encoded(const std::array<double,8>& raw,const std::string& encoding){if(encoding=="f64")return raw;Corners f;std::copy(raw.begin(),raw.end(),f.begin());if(encoding=="q8")f=encode_corners(f,Encoding::q8).decode();std::array<double,8> result;std::copy(f.begin(),f.end(),result.begin());return result;}
RaySegment cell(BoundedOracle& oracle,const MeasurementRay& ray,double lo,double hi,std::size_t cells){RaySegment s; s.low=lo;s.high=hi;double h=2./cells;auto u=(static_cast<long double>(lo)+hi)/2;for(unsigned axis=0;axis<3;++axis){auto p=static_cast<long double>(ray.origin[axis])+ray.direction[axis]*u;auto index=std::clamp<long long>(static_cast<long long>(std::floor((p+1)*cells/2)),0,cells-1);(&s.box.lo.x)[axis]=-1+index*h;(&s.box.hi.x)[axis]=-1+(index+1)*h;}for(unsigned c=0;c<8;++c)s.corners[c]=oracle.distance(s.box.point({double(c&1),double((c>>1)&1),double((c>>2)&1)}));return s;}
void write_segment(std::ostream& out,const RaySegment& s){std::array<double,16> v{s.low,s.high,s.box.lo.x,s.box.lo.y,s.box.lo.z,s.box.hi.x,s.box.hi.y,s.box.hi.z};std::copy(s.corners.begin(),s.corners.end(),v.begin()+8);out.write(reinterpret_cast<const char*>(v.data()),sizeof(v));}
std::vector<std::pair<int,MeasurementRay>> load_rays(const fs::path& file){std::ifstream in(file);std::vector<std::pair<int,MeasurementRay>> result;int group;MeasurementRay r;while(in>>group>>r.origin.x>>r.origin.y>>r.origin.z>>r.direction.x>>r.direction.y>>r.direction.z>>r.low>>r.high)result.push_back({group,r});if(result.empty())throw std::runtime_error("Missing measurement rays");return result;}
void root_row(std::ostream& out,unsigned depth,const std::string& encoding,std::size_t i,int group,const RayTransitions& result){out<<depth<<','<<encoding<<','<<i<<','<<group<<','<<result.ambiguous<<','<<result.zero_segments<<','<<result.tangencies.size()<<','<<result.jumps.size()<<',';for(std::size_t k=0;k<result.crossings.size();++k)out<<(k?";":"")<<result.crossings[k];out<<'\n';}
}
int main(int argc,char** argv){try{if(argc<5||(std::string(argv[1])=="field"&&argc<6))throw std::invalid_argument("virtual SPEC REF OUT | field BIN REF OUT GRID_N");std::string mode=argv[1];fs::path ref=argv[3],outdir=argv[4];if(fs::exists(outdir))throw std::runtime_error("Output already exists; preserve prior evidence");fs::create_directories(outdir);auto rays=load_rays(ref/"rays.txt");std::ofstream roots(outdir/"roots.csv");roots<<std::setprecision(17)<<"depth,encoding,ray,group,ambiguous,zero_segments,tangencies,jumps,roots\n";
if(mode=="virtual"){BoundedOracle oracle(GeometrySpec::read(argv[2]));std::ifstream p(ref/"probes.bin",std::ios::binary);Samples probes;Sample sample;while(p.read(reinterpret_cast<char*>(&sample),sizeof(sample)))probes.push_back(sample);if(probes.empty())throw std::runtime_error("No probes");std::ofstream predictions(outdir/"probes.csv"),cost(outdir/"cost.csv");predictions<<std::setprecision(17)<<"depth,encoding,probe,truth,prediction\n";cost<<"depth,logical,physical,hits,evictions,entries,peak_working_set,seconds\n";
for(unsigned depth:{7,9,12}){oracle.clear();auto start=std::chrono::steady_clock::now();std::size_t cells=std::size_t(1)<<depth;std::ofstream probe_cells(outdir/("probe_cells_"+std::to_string(depth)+".bin"),std::ios::binary);for(std::size_t i=0;i<probes.size();++i){MeasurementRay r{probes[i].point,{},0,1};auto s=cell(oracle,r,0,1,cells);write_segment(probe_cells,s);for(const std::string encoding:{"q8","f32","f64"}){auto v=encoded(s.corners,encoding);auto delta=probes[i].point-s.box.lo,width=s.box.hi-s.box.lo;Vec3 t{delta.x/width.x,delta.y/width.y,delta.z/width.z};double value=0;for(unsigned c=0;c<8;++c)value+=v[c]*(c&1?t.x:1-t.x)*(c&2?t.y:1-t.y)*(c&4?t.z:1-t.z);predictions<<depth<<','<<encoding<<','<<i<<','<<probes[i].distance<<','<<value<<'\n';}}
for(std::size_t i=0;i<rays.size();++i){guard();auto boundaries=grid_ray_boundaries(rays[i].second,cells);std::vector<RaySegment> segments;segments.reserve(boundaries.size()-1);std::ofstream evidence(outdir/("segments_"+std::to_string(depth)+"_"+std::to_string(i)+".bin"),std::ios::binary);for(std::size_t j=1;j<boundaries.size();++j){auto s=cell(oracle,rays[i].second,boundaries[j-1],boundaries[j],cells);write_segment(evidence,s);segments.push_back(s);}for(const std::string encoding:{"q8","f32","f64"}){auto decoded=segments;for(auto& s:decoded)s.corners=encoded(s.corners,encoding);root_row(roots,depth,encoding,i,rays[i].first,segmented_transitions(decoded,rays[i].second));}std::cout<<depth<<' '<<i+1<<'/'<<rays.size()<<std::endl;}cost<<depth<<','<<oracle.logical<<','<<oracle.physical<<','<<oracle.hits<<','<<oracle.evictions<<','<<oracle.entries()<<','<<peak()<<','<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<'\n';cost.flush();}
}else if(mode=="field"){std::ifstream f(argv[2],std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("Field missing");std::vector<unsigned char> data(static_cast<std::size_t>(f.tellg()));f.seekg(0);f.read(reinterpret_cast<char*>(data.data()),data.size());auto n=std::stoull(argv[5]);for(std::size_t i=0;i<rays.size();++i){std::vector<RaySegment> segments;if(!n)segments=packed_ray_segments(data.data(),rays[i].second);else{auto boundaries=grid_ray_boundaries(rays[i].second,n-1);for(std::size_t j=1;j<boundaries.size();++j){RaySegment s;s.low=boundaries[j-1];s.high=boundaries[j];auto point=rays[i].second.origin+rays[i].second.direction*((s.low+s.high)/2);std::size_t index[3];for(unsigned a=0;a<3;++a){index[a]=std::min<std::size_t>(std::size_t(std::max(0.,std::floor((point[a]+1)*(n-1)/2))),n-2);(&s.box.lo.x)[a]=-1+2.*index[a]/(n-1);(&s.box.hi.x)[a]=-1+2.*(index[a]+1)/(n-1);}for(unsigned c=0;c<8;++c){float v;auto offset=4*((index[2]+bool(c&4))*n*n+(index[1]+bool(c&2))*n+index[0]+bool(c&1));std::memcpy(&v,data.data()+offset,4);s.corners[c]=v;}segments.push_back(s);}}root_row(roots,0,n?"grid":"packed",i,rays[i].first,segmented_transitions(segments,rays[i].second));}}else throw std::runtime_error("Unknown mode");std::ofstream(outdir/"COMPLETE")<<"complete\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
